export type UploadStatus =
  | 'idle'
  | 'validating'
  | 'preprocessing'
  | 'requesting-upload'
  | 'uploading'
  | 'finalizing'
  | 'complete'
  | 'cancelled'
  | 'error';

export interface ImageUploadConfig {
  maxSizeBytes: number;
  allowedMimeTypes: string[];
  minWidth?: number;
  minHeight?: number;
  preprocess?: { maxWidth: number; quality: number };
  label?: string;
}

export interface UploadSession {
  sessionId: string;
  uploadUrl: string;
  expiresAt: string;
}

export interface UploadedAsset {
  assetId: string;
  url: string;
  width: number;
  height: number;
}

export interface UploadError {
  code: string;
  message: string;
  retryable: boolean;
}

export interface ImageUploadState {
  attemptId: string | null;
  file: File | null;
  previewUrl: string | null;
  status: UploadStatus;
  progress: { loaded: number; total?: number } | null;
  session: UploadSession | null;
  asset: UploadedAsset | null;
  error: UploadError | null;
}

export interface ImageUploadViewModel {
  canShowPreview: boolean;
  isIdle: boolean;
  isTransferring: boolean;
  isComplete: boolean;
  hasError: boolean;
}

export function toViewModel(state: ImageUploadState): ImageUploadViewModel {
  return {
    canShowPreview: Boolean(state.previewUrl),
    isIdle: state.status === 'idle',
    isTransferring: state.status === 'uploading',
    isComplete: state.status === 'complete' && state.asset !== null,
    hasError: state.status === 'error' && state.error !== null
  };
}

export type ValidationResult =
  | { ok: true; width: number; height: number }
  | { ok: false; error: UploadError };
